import { Injectable, inject, signal } from '@angular/core';
import { HttpClient } from '@angular/common/http';
import { Observable, tap } from 'rxjs';

export interface AuthUser {
  id: string;
  email: string;
  name: string;
  role: 'ADMIN' | 'USER';
}

@Injectable({ providedIn: 'root' })
export class AuthService {
  private readonly http = inject(HttpClient);
  readonly currentUser = signal<AuthUser | null>(null);
  readonly checked = signal(false);

  /** Fetches the current session once at app startup so every view shares the same auth state. */
  init(): void {
    this.fetchMe().subscribe({
      next: () => this.checked.set(true),
      error: () => {
        this.currentUser.set(null);
        this.checked.set(true);
      },
    });
  }

  register(email: string, name: string, password: string): Observable<AuthUser> {
    return this.http
      .post<AuthUser>('/api/auth/register', { email, name, password })
      .pipe(tap((user) => this.currentUser.set(user)));
  }

  login(email: string, password: string): Observable<AuthUser> {
    return this.http
      .post<AuthUser>('/api/auth/login', { email, password })
      .pipe(tap((user) => this.currentUser.set(user)));
  }

  logout(): Observable<void> {
    return this.http
      .post<void>('/api/auth/logout', {})
      .pipe(tap(() => this.currentUser.set(null)));
  }

  fetchMe(): Observable<AuthUser> {
    return this.http
      .get<AuthUser>('/api/auth/me')
      .pipe(tap((user) => this.currentUser.set(user)));
  }
}

