12	/** Lets the current user browse categories and toggle their subscriptions. */
13	export class CategoriesPage implements OnInit {
14	  private readonly categoriesService = inject(CategoriesService);
15	  private readonly subscriptionsService = inject(SubscriptionsService);
16	
17	  protected readonly categories = signal<Category[]>([]);
18	  protected readonly subscribedIds = signal<Set<string>>(new Set());
19	  protected readonly pendingIds = signal<Set<string>>(new Set());
20	  protected readonly loading = signal(true);
21	
22	  /** Loads all categories and the user's current subscriptions in parallel. */
23	  ngOnInit(): void {
24	    forkJoin({
25	      categories: this.categoriesService.list(),
26	      subscriptions: this.subscriptionsService.list(),
27	    }).subscribe({
28	      next: ({ categories, subscriptions }) => {
29	        this.categories.set(categories);
30	        this.subscribedIds.set(new Set(subscriptions.map((s) => s.category.id)));
31	        this.loading.set(false);
32	      },
33	      error: () => this.loading.set(false),
34	    });
35	  }
36	
37	  /** Subscribes or unsubscribes from a category, optimistically updating `subscribedIds` on success. */
38	  toggle(categoryId: string): void {
39	    const isSubscribed = this.subscribedIds().has(categoryId);
40	    this.setPending(categoryId, true);
41	
42	    const onSuccess = () => {
43	      const ids = new Set(this.subscribedIds());
44	      if (isSubscribed) {
45	        ids.delete(categoryId);
46	      } else {
47	        ids.add(categoryId);
48	      }
49	      this.subscribedIds.set(ids);
50	      this.setPending(categoryId, false);
51	    };
52	    const onError = () => this.setPending(categoryId, false);
53	
54	    if (isSubscribed) {
55	      this.subscriptionsService.unsubscribe(categoryId).subscribe({ next: onSuccess, error: onError });
56	    } else {
57	      this.subscriptionsService.subscribe(categoryId).subscribe({ next: onSuccess, error: onError });
58	    }
59	  }
60	
61	  /** Adds/removes a category id from the in-flight `pendingIds` set, used to disable its toggle while a request is outstanding. */
62	  private setPending(categoryId: string, pending: boolean): void {
63	    const ids = new Set(this.pendingIds());
64	    if (pending) {
