import json
import sys

path = r"C:\Users\starbuck\.claude\projects\c--sonrisa2\4efe100f-c48e-4a9d-a561-4e63bcc12e8a.jsonl"

prompts = []

with open(path, encoding="utf-8") as f:
    for line in f:
        line = line.strip()
        if not line:
            continue
        try:
            obj = json.loads(line)
        except json.JSONDecodeError:
            continue

        if obj.get("type") != "user":
            continue

        msg = obj.get("message", {})
        if msg.get("role") != "user":
            continue

        # Skip meta/sidechain/tool-result-only entries
        if obj.get("isMeta"):
            continue

        content = msg.get("content")
        text_parts = []

        if isinstance(content, str):
            text_parts.append(content)
        elif isinstance(content, list):
            for block in content:
                if isinstance(block, dict) and block.get("type") == "text":
                    text_parts.append(block.get("text", ""))
                # skip tool_result, tool_use, image blocks etc.

        text = "\n".join(t for t in text_parts if t).strip()
        if not text:
            continue

        # Skip pure system-reminder-only content
        stripped = text
        if stripped.startswith("<system-reminder>") and "</system-reminder>" in stripped:
            # check if there's real content after the reminder closes
            after = stripped.split("</system-reminder>")[-1].strip()
            if not after:
                continue

        prompts.append(text)

print(f"TOTAL_PROMPTS={len(prompts)}")
print("=" * 80)
for i, p in enumerate(prompts, 1):
    print(f"--- PROMPT {i} ---")
    print(p)
    print()

