import json

path = r"C:\Users\starbuck\.claude\projects\c--sonrisa2\4efe100f-c48e-4a9d-a561-4e63bcc12e8a.jsonl"

def truncate(s, n=300):
    s = s.replace("\n", " ")
    return s if len(s) <= n else s[:n] + "...[truncated]"

lines_out = []

with open(path, encoding="utf-8") as f:
    for lineno, line in enumerate(f, 1):
        line = line.strip()
        if not line:
            continue
        try:
            obj = json.loads(line)
        except json.JSONDecodeError:
            continue

        t = obj.get("type")
        msg = obj.get("message", {})
        role = msg.get("role")
        content = msg.get("content")

        if t == "user" and role == "user":
            if obj.get("isMeta"):
                continue
            text_parts = []
            tool_results = []
            if isinstance(content, str):
                text_parts.append(content)
            elif isinstance(content, list):
                for block in content:
                    if not isinstance(block, dict):
                        continue
                    if block.get("type") == "text":
                        text_parts.append(block.get("text", ""))
                    elif block.get("type") == "tool_result":
                        c = block.get("content")
                        if isinstance(c, list):
                            for cb in c:
                                if isinstance(cb, dict) and cb.get("type") == "text":
                                    tool_results.append(cb.get("text", ""))
                        elif isinstance(c, str):
                            tool_results.append(c)
            text = "\n".join(t2 for t2 in text_parts if t2).strip()
            if text:
                # detect interruption markers
                if "interrupted" in text.lower():
                    lines_out.append(f"L{lineno} [USER-INTERRUPT] {truncate(text,200)}")
                else:
                    lines_out.append(f"L{lineno} [USER] {truncate(text, 500)}")
            for tr in tool_results:
                if "interrupted" in tr.lower() or "user rejected" in tr.lower() or "user doesn't want" in tr.lower():
                    lines_out.append(f"L{lineno} [TOOL-RESULT/INTERRUPT] {truncate(tr,200)}")

        elif t == "assistant" and role == "assistant":
            if isinstance(content, list):
                for block in content:
                    if not isinstance(block, dict):
                        continue
                    if block.get("type") == "text":
                        txt = block.get("text", "").strip()
                        if txt:
                            lines_out.append(f"L{lineno} [ASSISTANT-TEXT] {truncate(txt, 300)}")
                    elif block.get("type") == "tool_use":
                        name = block.get("name")
                        inp = block.get("input", {})
                        summary = ""
                        if isinstance(inp, dict):
                            if "command" in inp:
                                summary = inp["command"]
                            elif "file_path" in inp:
                                summary = inp["file_path"]
                            elif "prompt" in inp:
                                summary = inp["prompt"]
                            elif "description" in inp:
                                summary = inp["description"]
                            else:
                                summary = json.dumps(inp)[:150]
                        lines_out.append(f"L{lineno} [TOOL-USE:{name}] {truncate(str(summary), 200)}")

with open(r"C:\Users\starbuck\AppData\Local\Temp\claude\c--sonrisa2\e9614c3d-30cb-4b2c-8b6d-94d11bf67c15\scratchpad\condensed.txt", "w", encoding="utf-8") as out:
    out.write("\n".join(lines_out))

print(f"Wrote {len(lines_out)} condensed entries")

